//! Explicit offline bootstrap only. No HTTP route or startup caller exists.
use super::{policy,serialize,bounded,target,Target};
use crate::{ApiError,ApiResult,db::PgStore};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
async fn no_administrator(tx:&tokio_postgres::Transaction<'_>)->ApiResult<()>{if tx.query_one("SELECT EXISTS(SELECT 1 FROM platform.users WHERE id NOT LIKE 'protocol:%' AND platform.eligible_roles_administrator(verified,disabled,roles,permissions))",&[]).await?.get::<_,bool>(0){return Err(ApiError::conflict("An eligible administrator already exists. Use the normal reviewed staff-access workflow instead."));}Ok(())}
fn proposed(before:&Target)->ApiResult<Target>{if !before.verified||before.disabled||before.roles.iter().any(|r|r=="restricted"||r=="banned"){return Err(ApiError::forbidden("Bootstrap requires an existing verified, enabled, unrestricted native account"));}let mut next=before.clone();next.bundles=policy::BOOTSTRAP.iter().map(|s|(*s).into()).collect();next.bundles.sort();let(r,p)=policy::selection(&next.bundles,true,&[])?;next.roles=r;next.permissions=p;Ok(next)}
fn summary(before:&Target,next:&Target,reason:&str)->Value{json!({"scope":"offline-native-admin-bootstrap","target":before,"proposed":next,"reason":reason,"effect":"Add only the listed local security grants, not content-moderation grants or original-service operator authority. The existing native sysop role hierarchy and baseline-permission behavior remain in effect. Replace all displayed previous nonbaseline roles and grants.","requiresNoEligibleAdministrator":true})}
fn digest(v:&Value)->ApiResult<String>{Ok(hex::encode(Sha256::digest(serde_json::to_vec(v).map_err(|_|ApiError::unavailable())?)))}
fn reason(value:&str)->ApiResult<()>{if value.trim().is_empty()||value.chars().count()>500||value.chars().any(|c|c.is_control()){return Err(ApiError::bad_request("Give a reason of 1 to 500 characters, without credentials or private contact details"));}Ok(())}
/// Read-only preview. Do not hold a database transaction while a human reviews it.
pub async fn preview(store:&PgStore,id:&str,why:&str)->ApiResult<Value>{reason(why)?;let mut db=store.client().await?;let tx=db.transaction().await?;bounded(&tx).await?;no_administrator(&tx).await?;let before=target(&tx,id,false).await?;let next=proposed(&before)?;let mut out=summary(&before,&next,why);out["digest"]=json!(digest(&out)?);tx.commit().await?;Ok(out)}
/// The confirmation digest binds every reviewed target/role/grant/reason field.
pub async fn apply(store:&PgStore,id:&str,why:&str,confirmed_digest:&str)->ApiResult<Value>{reason(why)?;if confirmed_digest.len()!=64{return Err(ApiError::bad_request("Use the exact reviewed bootstrap digest"));}let mut db=store.client().await?;let tx=db.transaction().await?;serialize(&tx).await?;no_administrator(&tx).await?;let before=target(&tx,id,true).await?;let next=proposed(&before)?;if digest(&summary(&before,&next,why))?!=confirmed_digest{return Err(ApiError::conflict("Bootstrap target or authority changed after review. Nothing was applied; start a new review."));}
 tx.execute("UPDATE platform.users SET roles=$2,permissions=$3,authority_bundles=$4,version=version+1,updated_at=clock_timestamp() WHERE id=$1",&[&id,&json!(next.roles),&json!(next.permissions),&json!(next.bundles)]).await?;
 let after=target(&tx,id,false).await?;let audit:i64=tx.query_one("INSERT INTO platform.security_audit(actor_kind,target_id,operation,reason,before_authority,after_authority,effects) VALUES('offline-bootstrap',$1,'bootstrap',$2,$3,$4,$5) RETURNING id",&[&id,&why,&json!(before),&json!(after),&json!({"reviewDigest":confirmed_digest,"sourceOperatorAuthority":false})]).await?.get(0);tx.commit().await?;Ok(json!({"scope":"offline-native-admin-bootstrap-receipt","targetId":id,"authorityVersion":after.authority_version,"auditId":audit.to_string(),"sourceOperatorAuthority":false}))}
